public static str FilterXml2String(str _xml, str _key) //TODO: Remove and use request Class instead
{
    XmlDocument requestXml = XmlDocument::newXml(_xml);
    XmlElement filtersElement,filtersChildElement;
    XmlNamedNodeMap addAttributes;
    int i;
    str ret = '';
    if (requestXml.root().getNamedElement(TFMConstants::requestData()) && requestXml.root().getNamedElement(TFMConstants::requestData()).getNamedElement(TFMConstants::filters()))
    {
        filtersElement = requestXml.root().getNamedElement(TFMConstants::requestData()).getNamedElement(TFMConstants::filters());

        // Loop over the add notes in the XML
        for (i = 0; i < filtersElement.childNodes().length(); i++)
        {
            filtersChildElement = filtersElement.childNodes().item(i);
            addAttributes = filtersChildElement.attributes();
            if (addAttributes.getNamedItem(TFMConstants::AttributeName()).value() == _key)
            {
                ret = addAttributes.getNamedItem(TFMConstants::AttributeValue()).value();
            }
        }

    }
    return ret;
}

