/// <summary>
/// Finds and returns all InventLocations that _user may access based on TFMInventLocationGroupRights
/// </summary>
/// <param name="_user">
/// UserId
/// </param>

public static InventLocation getAllowedInventLocations(userId _user)
{
    MobInventLocationsGroupRights   inventLocationRights;
    InventLocation                  inventLocations;
    UserGroupList                   userGroupList;
    Set                             usedLocs = new Set (Types::String);

    select count(RecId) from inventLocationRights;

    if (!inventLocationRights.RecId)
    {
        //If nothing har been setup, return all InventLocations
        select * from inventLocations;

        return inventLocations;
    }

    inventLocations.setTmp();


    while select inventLocationRights order by inventLocationRights.defaultLocation desc, inventLocationRights.InventLocationId asc
                join GroupId from userGroupList
                    where userGrouplist.userId == _user
                    && inventLocationRights.UserGroupId == userGroupList.GroupId
    {
        // Make sure that the warehouse exists before adding it
        // If a warehouse is deleted after it has been assigned

        if (!usedLocs.in(inventLocationRights.InventLocationId) && InventLocation::find(inventLocationRights.InventLocationId))
        {
            inventLocations.data(InventLocation::find(inventLocationRights.InventLocationId));
            inventLocations.doInsert(); // Do not call insert() - since it tries to insert in WHS tables
            usedLocs.add(inventLocationRights.InventLocationId);
        }

    }
    return inventLocations;

}

public static boolean isInventLocationAllowed(userId _user,InventLocationId _inventLocationId)
{
