}

public static str getAllowedInventLocationsList(userId _user)
{
    InventLocation                  inventLocations = MobHelper::getAllowedInventLocations(_user);
    str                             retList;
    while select inventLocations order by RecId
    {
        retList += (retList ? ';' : '') + inventLocations.InventLocationId;
    }
    return retList;
}

