public static str getItemBarcodes(ItemId _itemId, InventDim _inventDimCriteria)
{
    InventItemBarcode   inventItemBarcode;
    InventDimParm       inventDimParm;
    InventDim           inventDim;
    InventItemGTIN      inventItemGTIN;
    str                 result = '';
    //TODO: Not referenced. check if should be used instead
    // Get all the regular barcodes defined for this item
    // Only barcodes for marked for "scanning" are transferred
    inventDimParm = EcoResProductDimGroupSetup::newItemId(_itemId).inventDimParmActiveDimensions();

    while select inventItemBarcode
        where inventItemBarcode.ItemId         == _itemId
          && inventItemBarcode.UseForInput     == NoYes::Yes
        #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm)
    {
        result += inventItemBarcode.itemBarCode + ';';
    }

    // Now get all the GTIN codes
    while select inventItemGTIN
        where inventItemGTIN.ItemId         == _itemId
          #InventDimExistsJoin(inventItemGTIN.inventDimId, inventDim, _inventDimCriteria, inventDimParm)
    {
        result += inventItemGTIN.GlobalTradeItemNumber + ';';
    }

    // Remove the trailing ";"
    if (result)
    {
        result = strDel(result,strLen(result),1);
    }

    return result;
}

public static boolean IsArrivalJournalEnabled(InventLocationId _inventLocationId)
{
    MobInventLocationsPickReceiveTypes pickReceiveInfo;
    MobParameters                       parameters;

    pickReceiveInfo = MobInventLocationsPickReceiveTypes::find(_inventLocationId);
    if (pickReceiveInfo.OverwriteDefault)
    {
        return pickReceiveInfo.ReceiveArrival;
    }
    else
    {
        parameters = MobParameters::find();
        return parameters.ReceiveArrival;
    }
}

