/// <summary>
/// Configures the input types for header elements.
/// </summary>
/// <param name = "_addToThisElement">The XML Element to addd to.</param>
/// <param name = "_id">ID Attribute, Integer.</param>
/// <param name = "_name">Attribute name, string.</param>
/// <param name = "_label">Label attribute, string.</param>
/// <param name = "_labelWidth">Label width attribute, Integer.</param>
/// <param name = "_inputType">Input type attribute, string.</param>
/// <param name = "_dataTable">Data Table attribute, string.</param>
/// <param name = "_dataKeyColumn">Data key attribute, string.</param>
/// <param name = "_dataDisplayColumn">Data display column, string.</param>
/// <param name = "_clearOnClear">Clear on clear attribute, boolean.</param>
/// <param name = "_acceptBarcode">Accepts barcodes attribute, boolean.</param>
/// <param name = "_minValue">Minimum value attribute, Integer.</param>
/// <param name = "_maxValue">MAximum value attributem Integer.</param>
/// <param name = "_minDate">Minimum date attribute, UTC Datetime.</param>
/// <param name = "_maximumDate">Maximum date attribute, UTC Datetime.</param>
/// <param name = "_length">Length attribute, Integer.</param>
/// <param name = "_optional">Is the field Optional attribute, boolean.</param>
/// <param name = "_searchType">Search Type Attribute, String.</param>
/// <param name = "_linkedElement">Linked Element attribute, String. Optional.</param>
/// <param name = "_linkColumn">Link Column attribute, String. Optional.</param>
/// <param name = "_eanAi">Ean AI attribute, string. Optional.</param>
/// <param name = "_locked">Locked attribute, boolean. Optional.</param>
public static void createHeaderConfigurationElement(XmlElement _addToThisElement,
                                   int _id,
                                   str _name,
                                   str _headerLabel,
                                   str _label,
                                   int _labelWidth,
                                   TFMInputTypes _inputType,
                                   str _dataTable,
                                   str _dataKeyColumn,
                                   str _dataDisplayColumn,
                                   boolean _clearOnClear,
                                   boolean _acceptBarcode,
                                   int _minValue,
                                   int _maxValue,
                                   utcDateTime _minDate,
                                   utcDateTime _maximumDate,
                                   int _length,
                                   boolean _optional,
                                   str _searchType,
                                   str _linkedElement = '',
                                   str _linkColumn = '',
                                   str _eanAi = '',
                                   boolean _locked = false,
                                    str _defaultValue = '',
                                    boolean _visible = true)
{
    // Configures the input types for header elements
    XmlElement      addElement;
    XmlAttribute    attribute;
    XmlDocument     resultXML = _addToThisElement.ownerDocument();
    // Create the <add> element
    addElement      = resultXml.createElement(MobConstants::add());

    // Add the id attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeId());
    attribute.value(int2str(_id));
    addElement.attributes().setNamedItem(attribute);

    // Add the name attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeName());
    attribute.value(_name);
    addElement.attributes().setNamedItem(attribute);

    // Add the header attribute
    attribute       = resultXml.createAttribute('header');
    attribute.value(_headerLabel);
    addElement.attributes().setNamedItem(attribute);

    // Add the label attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeLabel());
    attribute.value(_label);
    addElement.attributes().setNamedItem(attribute);

    // Add the labelWidth attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeLabelWidth());
    attribute.value(int2str(_labelWidth));
    addElement.attributes().setNamedItem(attribute);

    // Add the inputType attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeInputType());
    attribute.value(enum2Symbol(enumNum(TFMInputTypes),_inputType));
    addElement.attributes().setNamedItem(attribute);

    // Add the dataTable attribute
    if (_dataTable != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeDataTable());
        attribute.value(_datatable);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the dataKeyColumn attribute
    if (_dataKeyColumn != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributDataKeyColumne());
        attribute.value(_dataKeyColumn);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the dataDisplayColumn attribute
    if (_dataDisplayColumn != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeDataDisplayColumn());
        attribute.value(_dataDisplayColumn);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the linkedElement attribute
    if (_linkedElement != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::LinkedElement());
        attribute.value(_linkedElement);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the linkedElement attribute
    if (_linkColumn != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::LinkColumn());
        attribute.value(_linkColumn);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the clearOnClear attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeClearOnClear());
    if (!_clearOnClear)
    {
        attribute.value(MobConstants::False());
    }
    else
    {
        attribute.value(MobConstants::True());
    }
    addElement.attributes().setNamedItem(attribute);

    // Add the acceptBarcode attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeAcceptBarcode());
    if (!_acceptBarcode)
    {
        attribute.value(MobConstants::False());
    }
    else
    {
        attribute.value(MobConstants::True());
    }
    addElement.attributes().setNamedItem(attribute);

    if (_visible == false)
    {
        attribute       = resultXml.createAttribute('visible');
        attribute.value(MobConstants::False());
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the minValue attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeMinValue());
    attribute.value(int2str(_minValue));
    addElement.attributes().setNamedItem(attribute);

    // Add the maxValue attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeMaxValue());
    attribute.value(int2str(_maxValue));
    addElement.attributes().setNamedItem(attribute);

    // Add the minDate attribute
    if (_minDate != dateTimeUtil::minValue())
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeMinDate());
        attribute.value( MobHelper::utcDateTime2Str(_minDate) );
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the maxDate attribute
    if (_maximumDate != dateTimeUtil::maxValue())
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeMaxDate());
        attribute.value( MobHelper::utcDateTime2Str(_maximumDate) );
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the length attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeLength());
    attribute.value(int2str(_length));
    addElement.attributes().setNamedItem(attribute);

    // Add the EAN attribute
    if (_eanAi)
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeEanAi());
        attribute.value(_eanAi);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the optional attribute
    attribute       = resultXml.createAttribute(MobConstants::AttributeOptional());
    if (!_optional)
    {
        attribute.value(MobConstants::False());
    }
    else
    {
        attribute.value(MobConstants::True());
    }
    addElement.attributes().setNamedItem(attribute);

    // Add the searchType attribute
    if (_searchType != '')
    {
        attribute       = resultXml.createAttribute(MobConstants::AttributeSearchType());
        attribute.value(_searchType);
        addElement.attributes().setNamedItem(attribute);
    }

    if (_locked)
    {
        attribute       = resultXml.createAttribute('locked');
        attribute.value(MobConstants::True());
        addElement.attributes().setNamedItem(attribute);
    }

    if (_defaultValue)
    {
        attribute       = resultXml.createAttribute('defaultValue');
        attribute.value(_defaultValue);
        addElement.attributes().setNamedItem(attribute);
    }

    // Add the created <add> element to the parent element
    _addToThisElement.appendChild(addElement);
}
